import { Component, DestroyRef, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HttpErrorResponse } from '@angular/common/http';
import { ActivatedRoute, Router } from '@angular/router';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { Capture, CaptureService, ReviewCapture } from './capture.service';
import { ErrorStateComponent, LoadingStateComponent } from '../../shared/states.component';
import { TuiButton, TuiTextfield, TuiInputDirective, TuiTitle, TuiLoader, TuiNotificationDirective } from '@taiga-ui/core';

@Component({
  selector: 'app-capture-review',
  standalone: true,
  imports: [FormsModule, ErrorStateComponent, LoadingStateComponent, TuiButton, TuiTextfield, TuiInputDirective, TuiTitle, TuiLoader, TuiNotificationDirective],
  template: `
    <section class="review">
      <header><h2 tuiTitle>Karte prüfen<span tuiSubtitle>Capture</span></h2></header>
      @let c = capture();
      @if (loading()) { <app-loading-state /> }
      @else if (error()) { <app-error-state [message]="error()" (retry)="load()" /> }
      @else if (c?.status === 'uploaded' || c?.status === 'analyzing') {
        <div class="analyzing">
          <tui-loader size="l" />
          <span tuiTitle>Bild wird analysiert…<span tuiSubtitle>Das kann einige Sekunden dauern.</span></span>
        </div>
      }
      @else if (c?.status === 'needsNewImage') {
        <app-error-state [message]="c?.error?.detail || 'Bitte ein neues Bild aufnehmen.'" />
        <button tuiButton type="button" appearance="secondary" (click)="newCapture()">Neues Bild</button>
      }
      @else if (c?.status === 'failed') {
        <app-error-state [message]="c?.error?.detail || 'Analyse fehlgeschlagen.'" />
        @if (c?.error?.retryable) { <button tuiButton type="button" appearance="secondary" (click)="retry()">Analyse wiederholen</button> }
      }
      @else if (c?.status === 'needsReview') {
        @if (c?.duplicate) {
          <div tuiNotification appearance="warning">
            <span tuiTitle>Dieses Bild ist bereits in der Sammlung. Beim Speichern ist eine Bestätigung nötig.</span>
          </div>
        }
        <div class="review-body">
          <img class="capture-image" [src]="c!.imageUrl" alt="Aufgenommene Karte" />
          <form (ngSubmit)="save()" #reviewForm="ngForm">
          <tui-textfield><label tuiLabel>Name</label><input tuiInput name="originalName" [(ngModel)]="model.originalName" required maxlength="200" /></tui-textfield>
          <tui-textfield><label tuiLabel>Deutscher Name</label><input tuiInput name="germanName" [(ngModel)]="model.germanName" maxlength="200" /></tui-textfield>
          <tui-textfield><label tuiLabel>Grund, falls nicht verfügbar</label><input tuiInput name="germanNameUnavailableReason" [(ngModel)]="model.germanNameUnavailableReason" maxlength="200" /></tui-textfield>
          <div class="pair">
            <tui-textfield><label tuiLabel>Kartennummer</label><input tuiInput name="collectorNumber" [(ngModel)]="model.collectorNumber" required maxlength="25" /></tui-textfield>
            <tui-textfield><label tuiLabel>Karten im Set</label><input tuiInput name="setTotal" [(ngModel)]="model.setTotal" maxlength="25" placeholder="z. B. 200" /></tui-textfield>
          </div>
          <div class="pair">
            <tui-textfield><label tuiLabel>Set-Code</label><input tuiInput name="setIdentifier" [(ngModel)]="model.setIdentifier" required /></tui-textfield>
            <tui-textfield><label tuiLabel>Set</label><input tuiInput name="setName" [(ngModel)]="model.setName" required /></tui-textfield>
          </div>
          <div class="pair">
            <tui-textfield><label tuiLabel>Sprache</label><input tuiInput name="language" [(ngModel)]="model.language" required /></tui-textfield>
            <tui-textfield><label tuiLabel>Variante</label><input tuiInput name="variantKey" [(ngModel)]="model.variantKey" required /></tui-textfield>
          </div>
          <div class="pair">
            <label class="select-field">
              <span class="select-label">Zustand</span>
              <select name="condition" [(ngModel)]="model.condition" required>
                @for (o of conditionOptions; track o) { <option [value]="o">{{ o }}</option> }
              </select>
            </label>
          </div>
          @if (c!.proposal?.condition?.limitations?.length) {
            <p class="note">Einschränkung: {{ c!.proposal!.condition.limitations.join(', ') }}</p>
          }
          @if (c!.proposal?.valuation?.status === 'available') {
            <div>
              <p>Aktueller Schätzwert: {{ ((c!.proposal?.valuation?.amountMinor || 0) / 100).toFixed(2) }} EUR</p>
              <p class="note">{{ c!.proposal!.valuation!.provider }} · {{ c!.proposal!.valuation!.method }}</p>
              @if (c!.proposal!.valuation!.sourceUrls.length) {
                <div class="source-links">
                  Quellen:
                  @for (url of c!.proposal!.valuation!.sourceUrls; track url) {
                    <a [href]="url" target="_blank" rel="noopener noreferrer">{{ sourceHost(url) }}</a>
                  }
                </div>
              }
            </div>
          }
          @if (c!.proposal?.aiCost; as aiCost) {
            <p class="note">
              KI-Analyse:
              @if (aiCost.estimatedAmount !== null) {
                ca. {{ formatAiCost(aiCost.estimatedAmount) }} {{ aiCost.currency }}
              } @else {
                Kosten für dieses Modell nicht hinterlegt
              }
              <br />
              {{ aiCost.provider }} · {{ aiCost.model }} ·
              {{ aiCost.inputTokens }} Input- / {{ aiCost.outputTokens }} Output-Tokens
              @if (aiCost.webSearchCalls) { · {{ aiCost.webSearchCalls }} Websuche(n) }
              @if (aiCost.isBatch) { · Batch }
            </p>
          }
          <button tuiButton type="submit" appearance="primary" [disabled]="saving() || reviewForm.invalid">{{ saving() ? 'Speichert…' : 'Bestätigen und speichern' }}</button>
          </form>
        </div>
      }
    </section>
  `,
  styles: [`
    .review{max-width:60rem}
    .review-body{display:grid;grid-template-columns:16rem 1fr;gap:1.5rem;align-items:start;margin-top:1rem}
    .capture-image{width:100%;border-radius:.6rem;position:sticky;top:1rem;background:var(--tui-background-neutral-1)}
    form{display:grid;gap:1.25rem}.pair{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
    @media(max-width:760px){.review-body{grid-template-columns:1fr}.capture-image{max-width:16rem;position:static}}
    .analyzing{display:flex;align-items:center;gap:1rem;padding:2rem 0}
    .select-field{display:flex;flex-direction:column;gap:.375rem;justify-content:center}
    .select-label{font:var(--tui-typography-body-s);color:var(--tui-text-secondary);padding-inline-start:.25rem}
    .select-field select{min-height:var(--tui-height-l);padding:0 1rem;border-radius:var(--tui-radius-l);background:var(--tui-background-neutral-1);color:var(--tui-text-primary);border:1px solid transparent;font:var(--tui-typography-body-m);cursor:pointer}
    .select-field select:focus{outline:none;border-color:var(--tui-border-focus)}
    .source-links{display:flex;flex-wrap:wrap;gap:.35rem .75rem;font-size:.875rem}
    button[type=submit]{justify-self:start}.note{color:var(--tui-text-tertiary)}
    @media(max-width:600px){.pair{grid-template-columns:1fr}}
  `],
})
export class CaptureReviewComponent implements OnInit {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly service = inject(CaptureService);
  private readonly destroyRef = inject(DestroyRef);
  readonly capture = signal<Capture | null>(null);
  readonly loading = signal(true);
  readonly saving = signal(false);
  readonly error = signal('');
  readonly conditionOptions = ['NM', 'LP', 'MP', 'HP', 'DMG'] as const;
  model: ReviewCapture = {
    catalogReferenceId: null, originalName: '', germanName: null, germanNameUnavailableReason: null,
    printedNumber: '', collectorNumber: '', setTotal: null,
    setIdentifier: '', setName: '', language: 'en', variantKey: 'standard', condition: 'NM',
  };

  ngOnInit(): void { this.load(); }

  load(): void {
    this.loading.set(true); this.error.set('');
    const id = this.route.snapshot.paramMap.get('captureId');
    if (!id) { this.error.set('Capture-ID fehlt.'); this.loading.set(false); return; }
    this.service.poll(id).pipe(takeUntilDestroyed(this.destroyRef)).subscribe({
      next: capture => { this.capture.set(capture); this.loading.set(false); if (capture.status === 'needsReview') this.populate(capture); },
      error: () => { this.error.set('Capture konnte nicht geladen werden.'); this.loading.set(false); },
    });
  }

  async save(): Promise<void> {
    const current = this.capture();
    if (!current) return;
    this.model.printedNumber = this.model.setTotal?.trim()
      ? `${this.model.collectorNumber.trim()}/${this.model.setTotal.trim()}`
      : this.model.collectorNumber.trim();
    this.saving.set(true); this.error.set('');
    try {
      const reviewed = await this.service.review(current, this.model);
      this.capture.set(reviewed);
      const finalized = await this.service.finalize(reviewed, false);
      await this.router.navigate(['/cards', finalized.body?.cardRecordId]);
    } catch (error) {
      const reviewed = this.capture();
      if (error instanceof HttpErrorResponse && error.status === 409 && error.error?.code === 'DUPLICATE_IMAGE') {
        if (confirm('Das Bild ist bereits gespeichert. Trotzdem als weiteres Exemplar anlegen?') && reviewed) {
          const finalized = await this.service.finalize(reviewed, true);
          await this.router.navigate(['/cards', finalized.body?.cardRecordId]);
        }
      } else {
        this.error.set('Die Karte konnte nicht gespeichert werden.');
      }
    } finally { this.saving.set(false); }
  }

  async retry(): Promise<void> {
    const current = this.capture();
    if (!current) return;
    try { this.capture.set(await this.service.retry(current)); this.load(); }
    catch { this.error.set('Die Analyse konnte nicht neu gestartet werden.'); }
  }

  newCapture(): void { void this.router.navigate(['/capture']); }

  formatAiCost(amount: number): string {
    if (amount > 0 && amount < 0.0001) return '< 0,0001';
    return amount.toLocaleString('de-DE', { minimumFractionDigits: 4, maximumFractionDigits: 4 });
  }

  sourceHost(url: string): string {
    try { return new URL(url).hostname.replace(/^www\./, ''); }
    catch { return 'Quelle'; }
  }

  private populate(capture: Capture): void {
    const proposal = capture.proposal;
    if (!proposal || this.model.originalName) return;
    const candidate = proposal.candidates[0];
    const number = this.splitNumber(candidate?.printedNumber ?? proposal.printedNumber.value ?? '');
    this.model = {
      catalogReferenceId: candidate?.catalogReferenceId ?? null,
      originalName: candidate?.printedName ?? proposal.printedName.value ?? '',
      germanName: candidate?.officialGermanName ?? proposal.officialGermanName.value,
      germanNameUnavailableReason: candidate?.officialGermanName || proposal.officialGermanName.value ? null : 'Nicht im Katalog verfügbar',
      printedNumber: number.printedNumber,
      collectorNumber: number.collectorNumber,
      setTotal: number.setTotal,
      setIdentifier: candidate?.setIdentifier ?? proposal.setIdentifier.value ?? '',
      setName: candidate?.setName ?? proposal.setName.value ?? '',
      language: candidate?.language ?? proposal.language.value ?? 'en',
      variantKey: candidate?.variantKey ?? proposal.variantKey.value ?? 'standard',
      condition: proposal.condition.grade ?? 'NM',
    };
  }

  private splitNumber(printedNumber: string): {printedNumber: string; collectorNumber: string; setTotal: string | null} {
    const slash = printedNumber.indexOf('/');
    if (slash < 0) return {printedNumber, collectorNumber: printedNumber.trim(), setTotal: null};
    return {
      printedNumber,
      collectorNumber: printedNumber.slice(0, slash).trim(),
      setTotal: printedNumber.slice(slash + 1).trim() || null,
    };
  }
}
